-- Portfolio admin and approved-knowledge storage.
CREATE TABLE IF NOT EXISTS facts (
  id TEXT PRIMARY KEY,
  category TEXT NOT NULL CHECK(category IN ('profile','contact','education','skills','experience','project','languages')),
  text_fr TEXT NOT NULL,
  text_en TEXT NOT NULL,
  aliases_json TEXT NOT NULL DEFAULT '[]',
  source_file TEXT NOT NULL,
  source_selector TEXT NOT NULL,
  public_url TEXT,
  approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_facts_approved ON facts(approved,category);
CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  type TEXT NOT NULL,
  description_fr TEXT NOT NULL,
  description_en TEXT NOT NULL,
  url TEXT NOT NULL,
  visible INTEGER NOT NULL DEFAULT 0 CHECK(visible IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_projects_visible ON projects(visible,sort_order);

-- All imported facts/projects are unapproved/hidden until reviewed in the admin dashboard.
